import pytest

from server.jobs.github_snapshot import (
    GitHubAPIError,
    deterministic_id,
    fetch_repo_docs,
    fetch_snapshot,
    split_slug,
)
from server.tests.jobs.conftest import b64

# Generated by the original Go implementation; the portfolio's Qdrant ingest
# upserts by these ids, so any drift duplicates the whole corpus.
GO_VECTORS = [
    ("profile:overview", "10515801-f007-5224-a265-5bde6e2bdaa2"),
    (
        "github:repo:https://github.com/kevin/portfolio",
        "ae0fb955-0a8e-5f11-b3a9-6fa22e1dc8c8",
    ),
    (
        "github_code:KevinDeBenedetti/portfolio:apps/api/main.go:1",
        "bf13a532-3948-557c-abf6-ff92eb10e953",
    ),
    ("resume:experience:slug:0", "d0425254-c85a-5282-87cf-118af3b05d39"),
    ("", "1b4db7eb-4057-5ddf-91e0-36dec72071f5"),
]


@pytest.mark.parametrize("key,expected", GO_VECTORS)
def test_deterministic_id_matches_go(key, expected):
    assert deterministic_id(key) == expected


def test_split_slug():
    assert split_slug("https://github.com/a/b", "me") == ("a", "b")
    assert split_slug("repo", "me") == ("me", "repo")


async def test_fetch_snapshot_skips_forks_and_collects_repo_errors(github):
    github.json(
        "/users/kevin",
        {"login": "kevin", "name": "Kevin", "followers": 3, "twitter_username": None},
    )
    github.json(
        "/users/kevin/repos",
        [
            {"full_name": "kevin/good", "fork": False, "archived": False},
            {"full_name": "kevin/forked", "fork": True, "archived": False},
            {"full_name": "kevin/old", "fork": False, "archived": True},
            {"full_name": "kevin/gone", "fork": False, "archived": False},
        ],
    )
    github.json(
        "/repos/kevin/good",
        {
            "name": "good",
            "description": None,
            "stargazers_count": 2,
            "html_url": "https://github.com/kevin/good",
            "default_branch": "dev",
        },
    )
    github.text("/repos/kevin/good/readme", "x" * 3100)

    client = github.client()
    snap, errors = await fetch_snapshot(client, "kevin")
    await client.close()

    assert snap.profile is not None
    assert snap.profile.name == "Kevin"
    assert snap.profile.twitter == ""
    assert [r.name for r in snap.repos] == ["good"]
    assert snap.repos[0].description == ""
    assert snap.repos[0].readme.endswith("[README truncated]")
    assert errors == ["kevin/gone: github repo kevin/gone: not found"]
    assert await client.default_branch("kevin", "good") == "dev"


async def test_rate_limit_fails_fast_after_first_exhaustion(github):
    github.json(
        "/repos/kevin/a/git/trees/main",
        {"message": "rate limited"},
        status=403,
        headers={"x-ratelimit-remaining": "0", "x-ratelimit-reset": "0"},
    )
    client = github.client()
    with pytest.raises(GitHubAPIError, match="rate limit exhausted"):
        await client.repo_tree("kevin", "a", "main")
    calls = len(github.calls)
    with pytest.raises(GitHubAPIError, match="rate limit exhausted"):
        await client.file_content("kevin", "a", "x.py")
    assert len(github.calls) == calls


async def test_fetch_repo_docs_filters_and_truncates(github):
    github.json("/repos/kevin/a", {"default_branch": "main"})
    github.json(
        "/repos/kevin/a/git/trees/main",
        {
            "tree": [
                {"path": "docs/guide.md", "type": "blob", "size": 10},
                {"path": "docs/empty.md", "type": "blob", "size": 0},
                {"path": "docs/big.md", "type": "blob", "size": 60_000},
                {"path": "docs/img.png", "type": "blob", "size": 10},
                {"path": "src/readme.md", "type": "blob", "size": 10},
            ]
        },
    )
    github.json(
        "/repos/kevin/a/contents/docs/guide.md",
        {"content": b64("abcdef"), "encoding": "base64"},
    )
    github.json(
        "/repos/kevin/a/contents/docs/empty.md",
        {"content": b64("  "), "encoding": "base64"},
    )
    client = github.client()
    docs = await fetch_repo_docs(client, "kevin", "a", limit=5, max_chars=3)
    assert [(d.path, d.content) for d in docs] == [
        ("docs/guide.md", "abc\n[...truncated]")
    ]


async def test_fetch_repo_docs_returns_empty_when_tree_missing(github):
    client = github.client()
    assert await fetch_repo_docs(client, "kevin", "nope", limit=5) == []
